CREATE FUNCTION public.test_expect_error(_sql text,_like text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER AS $$ BEGIN EXECUTE _sql; RAISE EXCEPTION 'TEST expected failure: %',_sql; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'TEST expected failure:%' OR SQLERRM NOT ILIKE _like THEN RAISE; END IF; END $$;
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000001"}',false);
DO $$
DECLARE c uuid:='10000000-0000-4000-8000-000000000001'; o jsonb; again jsonb; payload jsonb; b jsonb; sales jsonb; schedule jsonb; e uuid; posted jsonb; n integer;
BEGIN
 payload:=jsonb_build_object('requestId',gen_random_uuid(),'contactId','30000000-0000-4000-8000-000000000001','orderDate','2026-11-03','currencyCode','GBP','memo','Original memo','lines',jsonb_build_array(jsonb_build_object('description','Fractional line','accountId','20000000-0000-4000-8000-000000000001','quantity',1.5,'unitPriceMinor',1001,'discountMinor',0,'taxRateBps',0)));
 o:=public.save_purchase_order_atomic(c,payload);again:=public.save_purchase_order_atomic(c,payload);
 IF o->>'id'<>again->>'id' OR (SELECT count(*) FROM public.purchase_orders)<>1 OR (SELECT net_minor FROM public.purchase_order_lines)<>1501 THEN RAISE EXCEPTION 'PO persistence/replay/arithmetic failed'; END IF;
 PERFORM public.test_expect_error(format('SELECT public.save_purchase_order_atomic(%L,%L)',c,(payload||'{"memo":"Changed retry"}')::text),'%different order data%');
 payload:=payload||jsonb_build_object('orderId',o->>'id','version',1,'memo','Edited memo');o:=public.save_purchase_order_atomic(c,payload);
 IF (o->>'version')::int<>2 THEN RAISE EXCEPTION 'PO version did not advance'; END IF;
 PERFORM public.test_expect_error(format('SELECT public.save_purchase_order_atomic(%L,%L)',c,payload::text),'%reload%');
 PERFORM public.test_expect_error(format('SELECT public.save_purchase_order_atomic(%L,%L)',c,(payload||jsonb_build_object('version',2,'lines',jsonb_build_array(jsonb_build_object('description','Wrong company account','accountId','20000000-0000-4000-8000-000000000005','quantity',1,'unitPriceMinor',100))))::text),'%outside this organisation%');
 SELECT count(*) INTO n FROM public.purchase_orders;PERFORM set_config('test.fail_audit','on',true);
 PERFORM public.test_expect_error(format('SELECT public.save_purchase_order_atomic(%L,%L)',c,(payload-'orderId'-'version'||jsonb_build_object('requestId',gen_random_uuid()))::text),'%Injected audit failure%');
 PERFORM set_config('test.fail_audit','off',true);IF (SELECT count(*) FROM public.purchase_orders)<>n THEN RAISE EXCEPTION 'Audit failure left an orphan order'; END IF;
 b:=public.convert_purchase_order_atomic(c,(o->>'id')::uuid);again:=public.convert_purchase_order_atomic(c,(o->>'id')::uuid);
 IF b->>'billId'<>again->>'billId' OR (SELECT count(*) FROM public.purchase_bills)<>1 OR (SELECT discount_minor FROM public.purchase_bill_lines)<>0 OR (SELECT total_minor FROM public.purchase_bills)<>1501 OR (SELECT due_date FROM public.purchase_bills)<>'2026-11-17' THEN RAISE EXCEPTION 'PO conversion failed'; END IF;
 IF (SELECT count(*) FROM public.journals)<>0 THEN RAISE EXCEPTION 'Order conversion posted a journal'; END IF;
 IF (public.browse_purchase_orders(c,'Supplier %','all',1,25)->>'total')::int<>1 OR (public.browse_purchase_orders(c,'Supplier _','all',1,25)->>'total')::int<>0 THEN RAISE EXCEPTION 'Search did not escape literal wildcards'; END IF;
 payload:=jsonb_build_object('requestId',gen_random_uuid(),'contactId','30000000-0000-4000-8000-000000000002','orderDate','2026-11-03','currencyCode','GBP','fxRate',1,'lines',jsonb_build_array(jsonb_build_object('description','Sales fractional line','accountId','20000000-0000-4000-8000-000000000003','quantity',1.5,'unitPriceMinor',1001,'discountMinor',0,'taxRateBps',2000)));
 sales:=public.save_sales_order(c,payload);again:=public.save_sales_order(c,payload);
 IF sales->>'id'<>again->>'id' OR (sales->>'subtotal_minor')::bigint<>1502 OR (sales->>'tax_minor')::bigint<>300 THEN RAISE EXCEPTION 'Sales rounding/replay failed'; END IF;
 PERFORM public.test_expect_error(format('SELECT public.act_sales_order(%L,%L,1,%L,%L)',c,sales->>'id','invoice','2026-11-03'),'%not allowed%');
 PERFORM public.act_sales_order(c,(sales->>'id')::uuid,1,'confirm');
 b:=public.act_sales_order(c,(sales->>'id')::uuid,2,'invoice','2026-11-03');again:=public.act_sales_order(c,(sales->>'id')::uuid,2,'invoice','2026-11-03');
 IF b->>'invoiceId'<>again->>'invoiceId' OR (SELECT count(*) FROM public.sales_invoices)<>1 OR (SELECT total_minor FROM public.sales_invoices)<>1802 OR (SELECT status FROM public.sales_invoices)<>'draft' THEN RAISE EXCEPTION 'Sales conversion/replay failed'; END IF;
 payload:=jsonb_build_object('requestId',gen_random_uuid(),'kind','prepaid_expense','name','Annual cover','reference','Original bill TEST','debitAccountId','20000000-0000-4000-8000-000000000001','creditAccountId','20000000-0000-4000-8000-000000000002','totalMinor',10001,'startDate','2026-01-31','periods',3);
 schedule:=public.create_deferral_schedule(c,payload);again:=public.create_deferral_schedule(c,payload);
 IF schedule->>'id'<>again->>'id' OR (SELECT sum(amount_minor) FROM public.deferral_entries)<>10001 OR (SELECT array_agg(due_on ORDER BY period_no) FROM public.deferral_entries)<>ARRAY['2026-01-31'::date,'2026-02-28'::date,'2026-03-31'::date] THEN RAISE EXCEPTION 'Schedule allocation/month anchoring failed'; END IF;
 SELECT id INTO e FROM public.deferral_entries WHERE period_no=1;
 PERFORM public.test_expect_error(format('SELECT public.post_deferral_entry(%L,%L,%L)',c,e,'2026-01-31'),'%locked%');
 IF EXISTS(SELECT 1 FROM public.deferral_entries WHERE journal_id IS NOT NULL) OR EXISTS(SELECT 1 FROM public.journals) THEN RAISE EXCEPTION 'Locked posting left partial state'; END IF;
 posted:=public.post_deferral_entry(c,e,'2026-03-31');again:=public.post_deferral_entry(c,e,'2026-03-31');
 IF posted->>'journalId'<>again->>'journalId' OR (SELECT count(*) FROM public.journals)<>1 OR (SELECT sum(debit_minor-credit_minor) FROM public.journal_lines)<>0 OR (SELECT sum(debit_minor) FROM public.journal_lines)<>3333 THEN RAISE EXCEPTION 'Recognition journal failed'; END IF;
 PERFORM public.test_expect_error(format('SELECT public.cancel_deferral_schedule(%L,%L)',c,schedule->>'id'),'%entirely unposted%');
 PERFORM public.test_expect_error(format('SELECT public.save_sales_order(%L,%L)','10000000-0000-4000-8000-000000000002',payload::text),'%access denied%');
 PERFORM public.test_expect_error(format('SELECT public.reset_demo_company(%L)',c),'%not a demo company%');
END $$;
SELECT set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000002"}',false);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.sales_orders) OR EXISTS(SELECT 1 FROM public.deferral_schedules) OR EXISTS(SELECT 1 FROM public.deferral_entries) THEN RAISE EXCEPTION 'Two-tenant RLS isolation failed'; END IF;
 PERFORM public.test_expect_error('INSERT INTO public.sales_orders(company_id) VALUES(''10000000-0000-4000-8000-000000000002'')','%permission denied%');
 PERFORM public.test_expect_error('SELECT public.browse_purchase_orders(''10000000-0000-4000-8000-000000000001'')','%access denied%');
END $$;
RESET ROLE;
DO $$ BEGIN
 IF has_function_privilege('anon','public.post_deferral_entry(uuid,uuid,date)','EXECUTE') OR has_function_privilege('anon','public.save_sales_order(uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Anonymous mutation execution allowed'; END IF;
 IF (SELECT sum(debit_minor-credit_minor) FROM public.journal_lines)<>0 THEN RAISE EXCEPTION 'Unbalanced ledger'; END IF;
END $$;
